insert into conteudos (id, tipo, titulo, tema, resumo, icone, ordem, status, corpo, tags) values ('hamburguer', 'comer_fora', 'Hambúrguer', null, 'Como montar o lanche do jeito que cabe no seu dia.', 'hamburguer', 1, 'publicado', '{"introducao":"Compare as montagens antes de pedir. A diferença costuma estar no número de camadas, não no lanche em si.","decisoes":[{"id":"montagem","titulo":"A montagem do lanche","pergunta":"Quantas camadas o lanche tem?","observacoes":[],"opcoes":[{"id":"hamburguer-simples","titulo":"Montagem mais simples","descricao":null,"nivel":"melhor","energia":null,"detalhes":[],"tags":["simples"]},{"id":"hamburguer-denso","titulo":"Combinações mais densas em energia","descricao":null,"nivel":"ocasional","energia":null,"detalhes":[],"tags":["duplo","bacon","cheddar"]}]},{"id":"completa","titulo":"Como refeição livre completa","pergunta":null,"observacoes":[],"opcoes":[{"id":"hamburguer-completa","titulo":"Hambúrguer, batata frita pequena e refrigerante zero açúcar","descricao":null,"nivel":null,"energia":null,"detalhes":[],"tags":["refeicao livre"]}]}],"lembretes":[]}'::jsonb, array['hamburguer', 'lanche', 'burger']::text[]) on conflict (id) do nothing;
insert into conteudos (id, tipo, titulo, tema, resumo, icone, ordem, status, corpo, tags) values ('japonesa', 'comer_fora', 'Comida japonesa', null, 'Entradas, combinados e o que costuma pesar no rodízio.', 'japonesa', 2, 'publicado', '{"introducao":"Comece pelas entradas, escolha o combinado e deixe as preparações fritas e os molhos cremosos como parte menor da refeição.","decisoes":[{"id":"entradas","titulo":"Entradas","pergunta":"Por onde começar?","observacoes":[],"opcoes":[{"id":"sunomono","titulo":"Sunomono","descricao":null,"nivel":"melhor","energia":null,"detalhes":[],"tags":["sunomono","pepino"]},{"id":"missoshiro","titulo":"Missoshiro","descricao":null,"nivel":"melhor","energia":null,"detalhes":[],"tags":["missoshiro","sopa","miso"]},{"id":"edamame","titulo":"Edamame","descricao":null,"nivel":"melhor","energia":null,"detalhes":[],"tags":["edamame","soja"]}]},{"id":"principal","titulo":"Combinados","pergunta":"O que pedir depois das entradas?","observacoes":["Sugestão de 20 peças.","Peças simples, sem molho.","Molho shoyu tradicional ou light.","O salmão é um peixe muito saudável, mas é rico em gordura, o que eleva o valor calórico da refeição. Para reduzir, prefira atum, peixe branco ou camarão."],"opcoes":[{"id":"sashimi","titulo":"Sashimi","descricao":null,"nivel":"melhor","energia":null,"detalhes":[],"tags":["sashimi","peixe"]},{"id":"niguiri","titulo":"Niguiri","descricao":null,"nivel":"boa","energia":null,"detalhes":[],"tags":["niguiri","sushi"]},{"id":"temaki-simples","titulo":"Temaki simples, sem cream cheese","descricao":"Conta como meia refeição livre.","nivel":"boa","energia":null,"detalhes":[],"tags":["temaki"]}]},{"id":"ocasionais","titulo":"Preparações fritas e molhos cremosos","pergunta":"E os itens que aparecem no rodízio?","observacoes":[],"opcoes":[{"id":"fritos","titulo":"Preparações fritas","descricao":null,"nivel":"ocasional","energia":null,"detalhes":[],"tags":["frito","tempura","hot"]},{"id":"molhos-cremosos","titulo":"Molhos cremosos","descricao":null,"nivel":"ocasional","energia":null,"detalhes":[],"tags":["molho","cremoso"]}]}],"lembretes":[]}'::jsonb, array['japonesa', 'japones', 'sushi', 'sashimi', 'rodizio', 'temaki']::text[]) on conflict (id) do nothing;
insert into conteudos (id, tipo, titulo, tema, resumo, icone, ordem, status, corpo, tags) values ('massas', 'comer_fora', 'Massas', null, 'Quantidade da massa, proteína e molho.', 'massas', 3, 'publicado', '{"introducao":"Três escolhas definem o prato: quanto de massa, se entra proteína e qual molho acompanha.","decisoes":[{"id":"montagens","titulo":"Montagens que fecham uma refeição completa","pergunta":"Qual delas combina com o lugar onde você está?","observacoes":["Prefira o molho ao sugo.","Adicione proteína para trazer mais saciedade: massa e frango, massa e camarão, massa e carne magra.","Boa opção de restaurante: Spoleto."],"opcoes":[{"id":"massa-camarao","titulo":"Massa (200 g) com camarão (120 g), ricota temperada e molho pesto","descricao":null,"nivel":null,"energia":null,"detalhes":[],"tags":["camarao","pesto","ricota"]},{"id":"massa-frango","titulo":"Massa (100 g) com frango, legumes e molho pomodoro","descricao":null,"nivel":null,"energia":null,"detalhes":[],"tags":["frango","pomodoro","legumes"]},{"id":"massa-lasanha","titulo":"Lasanha bolonhesa","descricao":null,"nivel":null,"energia":null,"detalhes":[],"tags":["lasanha","bolonhesa"]}]}],"lembretes":[]}'::jsonb, array['massa', 'macarrao', 'italiano', 'molho', 'spoleto', 'lasanha']::text[]) on conflict (id) do nothing;
insert into conteudos (id, tipo, titulo, tema, resumo, icone, ordem, status, corpo, tags) values ('pizza', 'comer_fora', 'Pizza', null, 'Quantas fatias fecham uma refeição, por tipo de massa.', 'pizza', 4, 'publicado', '{"introducao":"A conta muda com a massa: quanto mais densa, menos fatias fecham a mesma refeição.","decisoes":[{"id":"fatias","titulo":"Quantas fatias","pergunta":"Qual é a massa da pizzaria?","observacoes":["Prefira opções com proteína e sem muita adição de queijo, como frango ou carne seca."],"opcoes":[{"id":"pizza-fina","titulo":"3 fatias de massa fina","descricao":null,"nivel":null,"energia":null,"detalhes":[],"tags":["massa fina"]},{"id":"pizza-grossa","titulo":"2 fatias de massa grossa ou de borda recheada","descricao":null,"nivel":null,"energia":null,"detalhes":[],"tags":["massa grossa","borda recheada"]}]}],"lembretes":[]}'::jsonb, array['pizza', 'pizzaria', 'fatia', 'borda']::text[]) on conflict (id) do nothing;
insert into conteudos (id, tipo, titulo, tema, resumo, icone, ordem, status, corpo, tags) values ('acai', 'comer_fora', 'Açaí', null, 'Tamanho da tigela e o que entra junto.', 'acai', 5, 'publicado', '{"introducao":"O tamanho decide se o açaí é a refeição livre inteira ou metade dela.","decisoes":[{"id":"tamanho","titulo":"O tamanho da tigela","pergunta":"Quanto vem no copo?","observacoes":[],"opcoes":[{"id":"acai-500","titulo":"500 ml com banana e leite condensado","descricao":"Fecha uma refeição livre completa.","nivel":null,"energia":null,"detalhes":[],"tags":["completa"]},{"id":"acai-300","titulo":"300 ml com 1 fruta e leite condensado","descricao":"Conta como meia refeição livre.","nivel":null,"energia":null,"detalhes":[],"tags":["meia"]}]}],"lembretes":[]}'::jsonb, array['acai', 'tigela', 'copo']::text[]) on conflict (id) do nothing;
insert into conteudos (id, tipo, titulo, tema, resumo, icone, ordem, status, corpo, tags) values ('doces', 'comer_fora', 'Doces e sobremesas', null, 'Cada uma destas conta como meia refeição livre.', 'doces', 6, 'publicado', '{"introducao":"Duas destas opções somam uma refeição livre completa.","decisoes":[{"id":"sobremesas","titulo":"Meias refeições doces","pergunta":"O que está na mesa?","observacoes":[],"opcoes":[{"id":"doce-gelato","titulo":"Gelato: 1 copo médio com 2 sabores","descricao":"Bacio di Latte, Lullo, Mi Garba.","nivel":null,"energia":null,"detalhes":[],"tags":["gelato","sorvete"]},{"id":"doce-cookie","titulo":"1 cookie artesanal grande, estilo americano","descricao":"Mr. Cheney, American Day.","nivel":null,"energia":null,"detalhes":[],"tags":["cookie"]},{"id":"doce-bolo","titulo":"1 fatia média de bolo ou torta com calda","descricao":null,"nivel":null,"energia":null,"detalhes":[],"tags":["bolo","torta"]},{"id":"doce-brownie","titulo":"1 brownie com 1 bola de sorvete","descricao":null,"nivel":null,"energia":null,"detalhes":[],"tags":["brownie","sorvete"]},{"id":"doce-milkshake","titulo":"Milkshake pequeno","descricao":"Bob''s, McDonald''s.","nivel":null,"energia":{"kcal":330,"mostrarKcal":false,"observacao":null},"detalhes":[],"tags":["milkshake"]},{"id":"doce-acai","titulo":"Açaí de 300 ml com 1 fruta e leite condensado","descricao":null,"nivel":null,"energia":null,"detalhes":[],"tags":["acai"]}]}],"lembretes":[]}'::jsonb, array['doce', 'sobremesa', 'chocolate', 'bolo', 'sorvete', 'cookie']::text[]) on conflict (id) do nothing;
insert into conteudos (id, tipo, titulo, tema, resumo, icone, ordem, status, corpo, tags) values ('subway', 'comer_fora', 'Subway', null, 'Montagens do balcão, das mais leves às mais ocasionais.', 'sanduiche', 7, 'publicado', '{"introducao":null,"decisoes":[{"id":"combos","titulo":"Sanduíche e bebida","pergunta":"Três montagens, da mais leve à mais ocasional.","observacoes":[],"opcoes":[{"id":"subway-melhor","titulo":"Frango assado","descricao":"Pão 9 grãos, sem queijo, molho mostarda e mel. Com refrigerante zero.","nivel":"melhor","energia":{"kcal":356,"mostrarKcal":true,"observacao":null},"detalhes":["Sanduíche — 356 kcal","Refrigerante zero — 0 kcal"],"tags":["sanduiche","combo"]},{"id":"subway-boa","titulo":"Frango empanado","descricao":"Pão italiano, molho barbecue. Com refrigerante zero.","nivel":"boa","energia":{"kcal":419,"mostrarKcal":true,"observacao":null},"detalhes":["Sanduíche — 419 kcal","Refrigerante zero — 0 kcal"],"tags":["sanduiche","combo"]},{"id":"subway-ocasional","titulo":"B.M.T. Italiano","descricao":"Três carnes e queijo. Com refrigerante zero.","nivel":"ocasional","energia":{"kcal":732,"mostrarKcal":true,"observacao":null},"detalhes":["Sanduíche — 732 kcal","Refrigerante zero — 0 kcal"],"tags":["sanduiche","combo"]}]}],"lembretes":[]}'::jsonb, array['subway', 'sanduiche', 'sub']::text[]) on conflict (id) do nothing;
